 const [kind,setKind]=useState<'batting'|'bowling'>('batting'),[hand,setHand]=useState('right'),[level,setLevel]=useState('beginner'),[step,setStep]=useState(1),[file,setFile]=useState<File|null>(null),[url,setUrl]=useState(''),[duration,setDuration]=useState(0),[trimStart,setTrimStart]=useState(0),[trimEnd,setTrimEnd]=useState(0),[consent,setConsent]=useState(false),[adult,setAdult]=useState(false),[busy,setBusy]=useState(false),[progress,setProgress]=useState(0),[result,setResult]=useState<Session|null>(null),[demo,setDemo]=useState(false),[notes,setNotes]=useState(''),[speed,setSpeed]=useState('1'),[blur,setBlur]=useState(true),[overlay,setOverlay]=useState(true),[recording,setRecording]=useState(false),[backendConsent,setBackendConsent]=useState(false);
 const video=useRef<HTMLVideoElement>(null),canvas=useRef<HTMLCanvasElement>(null),input=useRef<HTMLInputElement>(null),recorder=useRef<MediaRecorder|null>(null),stream=useRef<MediaStream|null>(null),recordTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const drills=content.drills??baseDrills;
