 async function api(path:string,opts:RequestInit={}){const r=await fetch(API+path,{...opts,headers:{...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...opts.headers},credentials:'include'});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map((item:{msg:string})=>item.msg).join('; '):'Request failed');return data;}
 useEffect(()=>{const shared=new URLSearchParams(window.location.hash.slice(1)).get('share');if(shared){setShareToken(shared);window.history.replaceState(null,'',window.location.pathname);}if(/^#(?:verify|reset)=/.test(window.location.hash)){setPage('account');setAuthAction(true);}try{setLang((localStorage.getItem('gc-lang') as Lang)||'bn');setSessions(JSON.parse(localStorage.getItem('gc-sessions')||'[]'));setJournal(JSON.parse(localStorage.getItem('gc-journal')||'[]'));}catch{}setNow(new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Dhaka'}).format(new Date()));api('/api/health').then(async r=>{if(r.service==='golicoach'){setServer(true);setServerVideo(r.server_video_available===true);const c=await api('/api/content');setContent({...defaults,...c,brand:/^Goli[ -]?Coach(?: AI)?$/i.test(c.brand||'')?defaults.brand:(c.brand||defaults.brand)});try{const u=await api('/api/me');const [records,entries]=await Promise.all([api('/api/records'),api('/api/journal')]);setSessions(records);setJournal(entries);setUser(u);}catch{}}}).catch(()=>{});return()=>{stream.current?.getTracks().forEach(tr=>tr.stop());if(recordTimer.current)clearTimeout(recordTimer.current);};},[]);
