 useEffect(()=>{if(!selectedDrill&&!modal)return;const previous=document.activeElement as HTMLElement|null;const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'){setSelectedDrill(null);setModal(null);}if(e.key==='Tab'){const nodes=document.querySelectorAll<HTMLElement>('.modal button,.modal a,.modal input,.modal textarea');if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',handler);return()=>{document.removeEventListener('keydown',handler);previous?.focus();};},[selectedDrill,modal]);

 function saveLocal(next:Session[]){try{localStorage.setItem('gc-sessions',JSON.stringify(next));setSessions(next);return true;}catch{notice(t('জায়গা পূর্ণ। রিপোর্ট ডাউনলোড করুন।','Storage full. Download your report.'));return false;}}
 async function persist(s:Session){try{if(server&&user){await api('/api/records',{method:'POST',body:JSON.stringify(s)});setSessions(await api('/api/records'));}else if(!saveLocal([...sessions.filter(x=>x.id!==s.id),s]))return;notice(t('সেশন সংরক্ষিত হয়েছে','Session saved'));}catch(e){notice(String(e));}}
 async function remove(id:string){if(!confirm(t('এই সেশন স্থায়ীভাবে মুছবেন?','Permanently delete this session?')))return;try{if(server&&user)await api('/api/records/'+id,{method:'DELETE'});if(server&&user)setSessions(sessions.filter(s=>s.id!==id));else saveLocal(sessions.filter(s=>s.id!==id));if(result?.id===id)setResult(null);notice(t('সেশন মুছে ফেলা হয়েছে','Session deleted'));}catch(e){notice(String(e));}}
 function download(data:unknown,name:string){const href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),500);}
 function newPractice(sample=false){setDemo(sample);setStep(sample?2:1);setResult(null);setFile(null);setUrl('');setConsent(false);setAdult(false);setNotes('');go('practice');}
 function chooseFile(f:File){if(!['video/mp4','video/webm','video/quicktime'].includes(f.type)||f.size>50*1024*1024){notice(t('MP4, WebM বা MOV দিন, সর্বোচ্চ ৫০ MB।','Use MP4, WebM or MOV, up to 50 MB.'));return;}setConsent(false);setAdult(false);setDuration(0);setTrimStart(0);setTrimEnd(0);setFile(f);setDemo(false);setUrl(URL.createObjectURL(f));setResult(null);setStep(1);}
 async function capture(){if(recording){recorder.current?.stop();return;}try{const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:960},audio:false});stream.current=media;const rec=new MediaRecorder(media);recorder.current=rec;const chunks:BlobPart[]=[];rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{if(recordTimer.current)clearTimeout(recordTimer.current);media.getTracks().forEach(track=>track.stop());setRecording(false);chooseFile(new File([new Blob(chunks,{type:'video/webm'})],'practice.webm',{type:'video/webm'}));};rec.start();setRecording(true);recordTimer.current=setTimeout(()=>rec.state==='recording'&&rec.stop(),30000);notice(t('রেকর্ডিং চলছে। ১০–৩০ সেকেন্ড পরে থামান।','Recording. Stop after 10–30 seconds.'));}catch{notice(t('ক্যামেরা খোলা যায়নি। ফোনে রেকর্ড করে আপলোড করুন।','Camera unavailable. Record on your phone and select the clip.'));}}
 function review(){if(!file||!consent||!adult){notice(t('ভিডিও ও সম্মতির ঘরগুলো পূরণ করুন।','Choose a clip and complete both consent checks.'));return;}const error=validateClip(file.type,file.size,trimEnd-trimStart);if(error){notice(t('১০–৩০ সেকেন্ডের অংশ নির্বাচন করুন।','Select a 10–30 second segment.'));return;}setStep(2);}
 async function analyze(){if(demo){setResult({id:crypto.randomUUID(),created_at:new Date().toISOString(),title:t('নমুনা অনুশীলন','Sample practice'),kind,hand,level,notes,favorite:false,is_demo:true,duration:15,frames:[],metrics:null,model_id:null});setStep(3);return;}if(!video.current)return;setBusy(true);setProgress(0);try{let frames:Frame[];if(backendConsent&&server&&serverVideo&&user&&file){const form=new FormData();form.append('file',file);form.append('consent','true');form.append('start',String(trimStart));form.append('end',String(trimEnd));const r=await api('/api/ai/analyze',{method:'POST',body:form});frames=r.frames;}else{frames=await analyzeVideo(video.current,trimStart,trimEnd,setProgress);}const metrics=summarize(frames);setResult({id:crypto.randomUUID(),created_at:new Date().toISOString(),title:t(kind==='batting'?'ব্যাটিং অনুশীলন':'বোলিং অনুশীলন',kind==='batting'?'Batting practice':'Bowling practice'),kind,hand,level,notes,favorite:false,is_demo:false,duration:trimEnd-trimStart,frames,metrics,model_id:'mediapipe-pose-landmarker-lite/float16/1'});setStep(3);setProgress(100);}catch(e){notice(t('বিশ্লেষণ হয়নি। ভিডিও দেখে নিজে নোট রাখুন। ','Analysis unavailable. You can still review and keep notes. ')+String(e));}finally{setBusy(false);}}
