 function paint(){const c=canvas.current,v=video.current;if(!c||!v)return;const ctx=c.getContext('2d');if(!ctx)return;c.width=v.videoWidth||640;c.height=v.videoHeight||360;ctx.clearRect(0,0,c.width,c.height);const frame=result?.frames.reduce<Frame|null>((best,f)=>!best||Math.abs(f.time-v.currentTime)<Math.abs(best.time-v.currentTime)?f:best,null);if(!frame||Math.abs(frame.time-v.currentTime)>.5)return;const pts=frame.landmarks;if(!overlay||pts.length!==33)return;ctx.strokeStyle='#cbff77';ctx.lineWidth=Math.max(2,c.width/300);for(const [a,b]of connectors){if((pts[a].visibility??0)<.5||(pts[b].visibility??0)<.5)continue;ctx.beginPath();ctx.moveTo(pts[a].x*c.width,pts[a].y*c.height);ctx.lineTo(pts[b].x*c.width,pts[b].y*c.height);ctx.stroke();}ctx.fillStyle='#ddff9a';pts.slice(11).forEach(p=>{if((p.visibility??0)>.5){ctx.beginPath();ctx.arc(p.x*c.width,p.y*c.height,3,0,2*Math.PI);ctx.fill();}});}
