 const heading=({home:t('আমার মাঠ','Your practice ground'),practice:t('নতুন অনুশীলন','New practice'),sessions:t('আমার সেশন','My sessions'),drills:t('ড্রিল লাইব্রেরি','Drill library'),sources:t('তথ্যসূত্র ও সীমাবদ্ধতা','Sources & limitations'),about:t('আমাদের কথা','About Goli-Coach'),help:t('সহায়তা','Help & feedback'),account:t('অ্যাকাউন্ট ও গোপনীয়তা','Account & privacy'),journal:t('প্র্যাকটিস জার্নাল','Practice journal'),compare:t('নিজের সেশন তুলনা','Compare your sessions')})[page];
 const sessionCards=(list:Session[])=>list.length?<div className="session-list">{list.map(s=><article className="session-row" key={s.id}><span className="session-icon"><Activity size={22}/></span><div className="grow"><button className="text-button session-title" onClick={()=>{setResult(s);setDemo(s.is_demo);setStep(3);setUrl('');go('practice');}}>{s.title}</button><p>{date(s.created_at)} · {t(s.kind==='batting'?'ব্যাটিং':'বোলিং',s.kind)} · {num(s.duration)}s {s.is_demo?'· DEMO':''}</p></div><span className="soft-pill">{s.model_id?t('পোজ বিশ্লেষণ','Pose review'):t('নিজের নোট','Manual notes')}</span><button className={'icon-button '+(s.favorite?'favorited':'')} aria-label="Favorite" onClick={()=>persist({...s,favorite:!s.favorite})}><Star size={17} fill={s.favorite?'currentColor':'none'}/></button><button className="icon-button" aria-label="Download report" onClick={()=>download(s,'golicoach-session.json')}><Download size={17}/></button><button className="icon-button" aria-label="Delete session" onClick={()=>remove(s.id)}><Trash2 size={17}/></button></article>)}</div>:<div className="empty"><Activity size={30}/><h3>{t('প্রথম সেশন এখান থেকেই','Your first session starts here')}</h3><p>{t('একটি ক্লিপ বিশ্লেষণ করুন অথবা নিজের পর্যবেক্ষণ লিখুন।','Review a clip or save your own observations.')}</p><button className="button primary" onClick={()=>newPractice()}>{t('অনুশীলন শুরু করুন','Start practising')}<ArrowRight size={16}/></button></div>;
